import type { NextConfig } from "next";
import legacyProducts from "./src/redirects.data.json";

/**
 * 301 redirects from the legacy site. The old URLs are indexed and some are
 * printed in datasheets and email signatures, so each one must land on the
 * matching model rather than a 404.
 *
 * The data is generated by `npm run content:build`, because the product
 * modules use the `@/` alias, which the Node loader that reads this config
 * cannot resolve. Regenerate after adding or renaming a product.
 */
const legacyRedirects = legacyProducts as {
  source: string;
  destination: string;
  permanent: boolean;
}[];

/**
 * Legacy category pages from the Chinese site, mapped to the closest English
 * family. These were section landing pages rather than product pages.
 */
const legacyCategoryRedirects = [
  { source: "/lljcyb", destination: "/products/flow", permanent: true },
  { source: "/yljcyb", destination: "/products/pressure", permanent: true },
  { source: "/wdcgq", destination: "/products/temperature", permanent: true },
  { source: "/csbcgq", destination: "/products/ultrasonic", permanent: true },
  { source: "/qtcgq", destination: "/products/gas", permanent: true },
  { source: "/qtcgq1", destination: "/products/gas", permanent: true },
  { source: "/fxcgq", destination: "/products/analytical", permanent: true },
  { source: "/wlwcp", destination: "/products/iot", permanent: true },
  { source: "/zdhyb", destination: "/products", permanent: true },
  { source: "/jjfa", destination: "/industries", permanent: true },
  { source: "/gywm", destination: "/about", permanent: true },
  { source: "/lxwm", destination: "/contact", permanent: true },
  { source: "/sy", destination: "/", permanent: true },
  { source: "/wzsy", destination: "/", permanent: true },
] as const;

const nextConfig: NextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,
  compress: true,
  images: {
    formats: ["image/avif", "image/webp"],
    deviceSizes: [360, 640, 828, 1080, 1200, 1600, 1920],
    imageSizes: [64, 96, 128, 256, 384, 512],
    // Two catalogue models still ship as vector placeholders until the
    // factory supplies photography. Serving them through the optimiser is
    // safe because the CSP below blocks any script inside the SVG.
    dangerouslyAllowSVG: true,
    contentDispositionType: "attachment",
    contentSecurityPolicy: "default-src 'self'; script-src 'none'; sandbox;",
  },
  async redirects() {
    return [...legacyCategoryRedirects, ...legacyRedirects];
  },
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          { key: "X-Frame-Options", value: "SAMEORIGIN" },
          {
            key: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=()",
          },
        ],
      },
      {
        // Never let the enquiry list or the admin API be cached by anything.
        source: "/admin/:path*",
        headers: [
          { key: "Cache-Control", value: "no-store, max-age=0" },
          { key: "X-Robots-Tag", value: "noindex, nofollow" },
        ],
      },
      {
        source: "/api/:path*",
        headers: [{ key: "Cache-Control", value: "no-store, max-age=0" }],
      },
      {
        source: "/images/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
        ],
      },
    ];
  },
};

export default nextConfig;
